// Approved staging-only release overlay. No credentials, private records or migrations are executed.
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {inflateSync} from 'node:zlib';
const digest=b=>createHash('sha256').update(b).digest('hex');
const archive=fs.readFileSync('hebrew-quest-family-staging-source.zip');
if(digest(archive)!=="a7d9db69a51b7528e4d6b7ba3aa9735842d3388bb9aad59be87ed0b083c8fb5a")throw Error('Unexpected source archive. Stop before changing release files.');
const files=JSON.parse(inflateSync(Buffer.from("",'base64')).toString('utf8'));
for(const [name,entry]of Object.entries(files)){
 const target=path.resolve(name),root=process.cwd()+path.sep,bytes=Buffer.from(entry.data,'base64');
 if(!target.startsWith(root)||name.startsWith('.')&&!name.startsWith('.gitignore')||digest(bytes)!==entry.sha256)throw Error('Release path or checksum mismatch.');
}
for(const [name,entry]of Object.entries(files)){fs.mkdirSync(path.dirname(name),{recursive:true});fs.writeFileSync(name,Buffer.from(entry.data,'base64'));}
console.log('Applied approved family staging release: '+Object.keys(files).length+' verified source files; live AI disabled.');
